-- UNAPPLIED FORWARD MIGRATION (2026-08-16)
--
-- Move inland beach coordinates onto the waterline.
--
-- A Mapbox water-layer audit of all 346 beaches found 99 whose stored point is
-- more than 120m from water; 247 were already fine. Del Mar sat 276m inland on
-- Camino Del Mar. beaches.lat/lon is not only the map pin — it feeds NOAA/CDIP
-- station selection and nearby-spot distance — so those beaches were reading
-- conditions from a point that is not the break.
--
-- Corrects 95 of them, every one verified to face open ocean. Candidates were
-- generated by stepping seaward until within 40m of water (along the beach's
-- aspect_deg where present, otherwise along the bearing to the nearest water
-- polygon), then each candidate was re-tested 1km and 3km further out. Only
-- points still in water at both distances are included here: open ocean stays
-- water for kilometres, an inland creek or lagoon does not.
--
-- 20 candidates initially FAILED that test, because walking toward the NEAREST
-- water found inland rivers and creeks and led away from the coast (confirmed
-- by eye: rosarito-beach went 800m east to a river, crystal-cove 1km north into
-- the hills). Those were re-solved by sweeping all 360 degrees in 20-degree
-- steps and accepting only a bearing whose water is still water at +1km and
-- +3km. 18 of the 20 resolved that way and are included; spot-checked on
-- rendered maps, rosarito-beach now lands on Playa de Rosarito and crystal-cove
-- on the shoreline at PCH.
--
-- Two remain excluded because no open ocean exists within 2km on any bearing,
-- meaning the stored point is wrong by more than a nudge:
--   scarborough-beach-scarborough-me
--   florence-south-jetty
--
-- Caveat on the large moves: corrections over ~1km place the beach on the
-- correct coastline, but not necessarily at the exact named break.
-- andrew-molera-river-mouth-big-sur-ca lands on the coast south of the river
-- mouth itself. Still a large improvement on 2km inland, and per-row reversible
-- from beach_coordinate_corrections.
--
-- Keyed on beaches.id: slug carries only non-unique indexes, so a duplicate
-- slug would silently update two rows.
--
-- Reversible: prior values are captured in beach_coordinate_corrections before
-- the UPDATE. Rollback statement at the bottom of this file.

BEGIN;

CREATE TABLE IF NOT EXISTS public.beach_coordinate_corrections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  beach_id uuid NOT NULL REFERENCES public.beaches(id) ON DELETE CASCADE,
  slug text NOT NULL,
  old_lat double precision NOT NULL,
  old_lon double precision NOT NULL,
  new_lat double precision NOT NULL,
  new_lon double precision NOT NULL,
  reason text NOT NULL,
  corrected_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.beach_coordinate_corrections ENABLE ROW LEVEL SECURITY;

COMMENT ON TABLE public.beach_coordinate_corrections IS
  'Audit + rollback source for beach lat/lon corrections. One row per changed beach.';

CREATE TEMP TABLE _coord_fix (beach_id uuid PRIMARY KEY, new_lat double precision, new_lon double precision) ON COMMIT DROP;


SELECT b.id, b.slug, b.lat, b.lon, f.new_lat, f.new_lon,
       'inland-coordinate-audit-2026-08-16: stepped seaward to the waterline, open-ocean verified at +1km and +3km'
FROM public.beaches b
JOIN _coord_fix f ON f.beach_id = b.id
WHERE b.lat IS DISTINCT FROM f.new_lat OR b.lon IS DISTINCT FROM f.new_lon;

UPDATE public.beaches b
SET lat = f.new_lat,
    lon = f.new_lon
FROM _coord_fix f
WHERE f.beach_id = b.id
  AND (b.lat IS DISTINCT FROM f.new_lat OR b.lon IS DISTINCT FROM f.new_lon);

COMMIT;

